    /**
     * Converts text such as "12.5" to whole basis points (1250), by hand.
     * Accepts up to two decimal places and a value from 0 to 100 inclusive.
     */
    private static long parseBasisPoints(String percent) {
        String text = percent == null ? "" : percent.trim();
        int dot = text.indexOf('.');
        String whole = dot < 0 ? text : text.substring(0, dot);
        String fraction = dot < 0 ? "" : text.substring(dot + 1);

        boolean wellFormed = !(whole.isEmpty() && fraction.isEmpty())
                && whole.length() <= 3 && fraction.length() <= 2
                && isDigits(whole) && isDigits(fraction)
                && (dot < 0 || text.indexOf('.', dot + 1) < 0);
        if (!wellFormed) {
            throw new ShopProblem("invalid-percent", "Not a percentage with at most two decimals: " + percent);
        }

        long wholePart = whole.isEmpty() ? 0 : Long.parseLong(whole);
        long fractionPart = fraction.isEmpty() ? 0 : Long.parseLong(fraction) * (fraction.length() == 1 ? 10 : 1);
        long basisPoints = wholePart * 100 + fractionPart;
        if (basisPoints > 10000) {
            throw new ShopProblem("percent-out-of-range", "Percentage must be between 0 and 100: " + percent);
        }
        return basisPoints;
    }

    private static boolean isDigits(String s) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return true;
    }
