import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import com.wolinski.shop.platform.ShopProblem;
import java.time.Instant;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;

class ApplyDiscountTest {

    private static final Instant NOW = Instant.parse("2026-10-01T10:00:00Z");

    @Test
    void halfACentOfADiscountRoundsUp() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(100), NOW);

            orders.applyDiscount(id, "0.5");

            assertEquals(Money.pln(99), orders.summary(id).total());
        }
    }

    @Test
    void aFractionalPercentIsLoweredByExactBasisPoints() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(10000), NOW);

            orders.applyDiscount(id, "12.5");

            assertEquals(Money.pln(8750), orders.summary(id).total());
        }
    }

    @Test
    void wholeAndTwoDecimalPercentsAreAccepted() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(10000), NOW);

            orders.applyDiscount(id, "10");
            orders.applyDiscount(id, "0.25");

            assertEquals(Money.pln(8975), orders.summary(id).total());
        }
    }

    @Test
    void oneHundredPercentLeavesNothingToPay() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(1234), NOW);

            orders.applyDiscount(id, "100");

            assertEquals(Money.pln(0), orders.summary(id).total());
        }
    }

    @Test
    void textThatIsNotAPercentageIsRefused() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(1000), NOW);

            for (String bad : new String[] {"", " ", ".", "abc", "-5", "1e2", "1,5", "1.2.3", "1.234", "1000"}) {
                ShopProblem p = assertThrows(ShopProblem.class, () -> orders.applyDiscount(id, bad));
                assertEquals(bad.equals("1000") ? "percent-out-of-range" : "invalid-percent", p.code());
            }
            assertEquals(Money.pln(1000), orders.summary(id).total());
        }
    }
}
}

